insert into public.learning_paths (id, title, description, badge_icon, display_order) values
  ('pre-security', 'Pre-Security', 'Essential computing architecture, network protocols, Linux/Windows operating systems, and command-line mechanics required before offensive and defensive security.', 'shield', 1),
  ('cyber-security', 'Cyber Security Foundations', 'Master the core principles of cybersecurity: the CIA Triad, threat modeling, authentication architectures, applied cryptography, malware classification, and incident response frameworks.', 'lock', 2),
  ('defensive-security', 'Defensive Security', 'Specialized defensive security training: SOC operations, Windows/Linux log analysis, Wireshark traffic inspection, SIEM detection engineering, digital forensics, and incident containment.', 'security', 3),
  ('offensive-security', 'Offensive Security', 'Specialized offensive security training: Rules of engagement, network reconnaissance, service enumeration, OWASP Top 10 web exploitation, privilege escalation, and executive remediation reporting.', 'swords', 4)
insert into public.rooms (id, path_id, level_number, title, description, xp_reward, total_questions, display_order) values
  ('room-01', 'pre-security', 1, 'Introduction to Computers', 'Understand computer hardware, CPU execution cycles, memory hierarchies, and hardware privilege rings.', 50, 3, 1),
  ('room-02', 'pre-security', 1, 'How the Internet Works', 'Explore the global packet-switched Internet, IP routing, Autonomous Systems, and BGP peering.', 50, 3, 2),
  ('room-03', 'pre-security', 1, 'Networking Fundamentals', 'Master Local Area Networks (LAN), MAC addresses, IPv4 vs IPv6 addressing, and subnet masks.', 50, 3, 3),
  ('room-04', 'pre-security', 1, 'Network Protocols and Ports', 'Demystify Layer 4 transport protocols: TCP reliable connections, the 3-Way Handshake, UDP datagrams, and standardized network ports.', 50, 3, 4),
  ('room-05', 'pre-security', 1, 'Linux Fundamentals', 'Master the operating system of cybersecurity: the hierarchical Linux filesystem, core directory roles, and essential file commands.', 50, 3, 5),
  ('room-06', 'pre-security', 1, 'Windows Fundamentals', 'Explore Windows operating system architecture, the Registry, NTFS security permissions, and core administrative services.', 50, 3, 6),
  ('room-07', 'pre-security', 1, 'Command-Line Fundamentals', 'Unlock the full power of the shell: input/output redirection, pipes, grep pattern filtering, and command chaining.', 50, 3, 7),
  ('room-08', 'pre-security', 1, 'Web Fundamentals', 'Master the foundations of the World Wide Web: HTTP request/response cycles, headers, cookies, and client-server architectures.', 50, 3, 8),
  ('room-09', 'pre-security', 1, 'Introduction to Virtualization', 'Explore virtualization technology: Type-1 vs Type-2 Hypervisors, containers vs virtual machines, and snapshot rollbacks for safe security testing.', 50, 3, 9),
  ('room-10', 'pre-security', 1, 'Introduction to Cybersecurity', 'Synthesize your pre-security foundations into modern cybersecurity: the threat landscape, adversary motivations, and defense in depth.', 50, 3, 10),
  ('room-11', 'cyber-security', 2, 'Security Fundamentals', 'Establish the foundational security mindset: asset valuation, adversary attack surface calculation, and threat vectors.', 50, 3, 11),
  ('room-12', 'cyber-security', 2, 'CIA Triad and Security Principles', 'Deep dive into the core guiding model of information security: Confidentiality, Integrity, and Availability.', 50, 3, 12),
  ('room-13', 'cyber-security', 2, 'Threats, Vulnerabilities and Risks', 'Deconstruct the fundamental equation of cybersecurity: Risk = Threat × Vulnerability × Impact.', 50, 3, 13),
  ('room-14', 'cyber-security', 2, 'Authentication and Access Control', 'Master identity security: password hygiene, Multi-Factor Authentication (MFA), and Access Control models (DAC, MAC, RBAC, ABAC).', 50, 3, 14),
  ('room-15', 'cyber-security', 2, 'Cryptography Fundamentals', 'Master practical cryptography: symmetric ciphers (AES), asymmetric key pairs (RSA/ECC), cryptographic hashing, and digital certificates.', 50, 3, 15),
  ('room-16', 'cyber-security', 2, 'Malware and Attack Concepts', 'Deconstruct malicious software: viruses, worms, trojans, ransomware, rootkits, command & control (C2), and the adversary attack lifecycle.', 50, 3, 16),
  ('room-17', 'cyber-security', 2, 'Security Architecture', 'Design enterprise defensive architectures: Next-Gen Firewalls, Demilitarized Zones (DMZ), network micro-segmentation, and Zero Trust.', 50, 3, 17),
  ('room-18', 'cyber-security', 2, 'Vulnerability Management', 'Master the vulnerability management lifecycle: asset discovery, automated vulnerability scanning, vulnerability triage, and patch verification.', 50, 3, 18),
  ('room-19', 'cyber-security', 2, 'Security Monitoring Fundamentals', 'Explore enterprise security monitoring: telemetry collection, log aggregation, Intrusion Detection Systems (IDS/IPS), and SIEM integration.', 50, 3, 19),
  ('room-20', 'cyber-security', 2, 'Introduction to Incident Response', 'Master the emergency management of cybersecurity: the NIST/SANS Incident Response lifecycle, containment strategies, and evidence preservation.', 50, 3, 20),
  ('room-21', 'defensive-security', 3, 'Introduction to Blue Team Operations', 'Enter the world of enterprise defense: the blue team mission, defending business assets, and operational threat hunting.', 50, 3, 21),
  ('room-22', 'defensive-security', 3, 'Security Operations Centre Fundamentals', 'Explore the engine room of enterprise defense: SOC tiers (Tier 1, Tier 2, Tier 3), alert triage, escalation workflows, and SLA metrics.', 50, 3, 22),
  ('room-23', 'defensive-security', 3, 'Log Analysis Fundamentals', 'Master the language of digital evidence: syslog formats, timestamp normalization, regex parsing, and multi-source event correlation.', 50, 3, 23),
  ('room-24', 'defensive-security', 3, 'Windows Event Logs', 'Master Windows forensic auditing: Event Viewer, essential Security Event IDs (4624, 4625, 4688, 7045), and Sysmon telemetry.', 50, 3, 24),
  ('room-25', 'defensive-security', 3, 'Linux Log Analysis', 'Master Linux forensic investigation: /var/log hierarchy, auth.log brute-force detection, systemd journalctl querying, and auditd system auditing.', 50, 3, 25),
  ('room-26', 'defensive-security', 3, 'Network Traffic Analysis', 'Master packet forensics: live packet capture with tcpdump, deep protocol inspection in Wireshark, TCP stream reassembly, and C2 beacon detection.', 50, 3, 26),
  ('room-27', 'defensive-security', 3, 'SIEM Fundamentals', 'Explore enterprise Security Information and Event Management (SIEM): data ingestion pipelines, index parsing, SPL/KQL correlation queries, and alert tuning.', 50, 3, 27),
  ('room-28', 'defensive-security', 3, 'Threat Intelligence', 'Master cyber threat intelligence (CTI): Strategic, Tactical, and Operational CTI, the Pyramid of Pain, STIX/TAXII standards, and OSINT threat feeds.', 50, 3, 28),
  ('room-29', 'defensive-security', 3, 'Incident Detection and Response', 'Execute live incident response playbooks: host network isolation, credential revocation, artifact collection, and remediation validation.', 50, 3, 29),
  ('room-30', 'defensive-security', 3, 'Digital Forensics Fundamentals', 'Master digital forensic acquisition: memory dumping, bit-stream disk imaging (dd/dcfldd), write-blockers, and file carving (scalpel/foremost).', 50, 3, 30),
  ('room-31', 'defensive-security', 3, 'Endpoint Security', 'Master modern endpoint protection: Antivirus signatures vs Endpoint Detection & Response (EDR), behavioral heuristics, and memory injection detection.', 50, 3, 31),
  ('room-32', 'defensive-security', 3, 'Defensive Security Capstone', 'Synthesize your complete defensive training: investigate a simulated enterprise breach across network, endpoint, and SIEM logs, contain the adversary, and formulate remediation.', 50, 3, 32),
  ('room-33', 'offensive-security', 4, 'Introduction to Ethical Hacking', 'Enter the world of authorized security testing: ethical hacking mindsets, testing methodologies, and penetration testing phases.', 50, 3, 33),
  ('room-34', 'offensive-security', 4, 'Rules of Engagement and Legal Boundaries', 'Master the legal framework of offensive security: CFAA, Computer Misuse Act, Rules of Engagement (RoE), and out-of-scope liabilities.', 50, 3, 34),
  ('room-35', 'offensive-security', 4, 'Reconnaissance Fundamentals', 'Master open-source intelligence (OSINT): passive footprinting, WHOIS registration audits, DNS enumeration, and search engine dorking.', 50, 3, 35),
  ('room-36', 'offensive-security', 4, 'Network Enumeration', 'Master active network mapping with Nmap: ping sweeps, TCP SYN stealth scans, full connect scans, UDP scanning, and port timing templates.', 50, 3, 36),
  ('room-37', 'offensive-security', 4, 'Service Enumeration', 'Extract detailed service intelligence: banner grabbing, software version detection (-sV), Nmap Scripting Engine (NSE), and vulnerability mapping.', 50, 3, 37),
  ('room-38', 'offensive-security', 4, 'Web Application Fundamentals', 'Analyze modern web applications through a security lens: client vs server architectures, DevTools DOM inspection, and Burp Suite HTTP proxying.', 50, 3, 38),
  ('room-39', 'offensive-security', 4, 'OWASP Top 10', 'Explore the canonical web vulnerability benchmark: the OWASP Top 10 web application security risks and threat mitigation.', 50, 3, 39),
  ('room-40', 'offensive-security', 4, 'Web Vulnerability Assessment', 'Master practical web vulnerability discovery: Cross-Site Scripting (Reflected, Stored, DOM), SQL Injection (SQLi), and Insecure Direct Object References (IDOR).', 50, 3, 40),
  ('room-41', 'offensive-security', 4, 'Authentication Security Testing', 'Test authentication mechanisms: brute-force rate-limiting, credential stuffing with Hydra, JSON Web Token (JWT) signature flaws, and session fixation.', 50, 3, 41),
  ('room-42', 'offensive-security', 4, 'Vulnerability Validation in a Lab', 'Master the safe construction of Proof-of-Concept (PoC) exploits in isolated lab containers without causing collateral disruption.', 50, 3, 42),
  ('room-43', 'offensive-security', 4, 'Linux Privilege Escalation Fundamentals', 'Elevate privileges on Linux systems: SUID binaries, misconfigured sudo permissions (sudo -l), cron job hijacking, and readable /etc/shadow files.', 50, 3, 43),
  ('room-44', 'offensive-security', 4, 'Windows Privilege Escalation Fundamentals', 'Elevate privileges on Windows systems: Unquoted Service Paths, weak service permissions, token impersonation (SeImpersonate), and SAM hash dumping.', 50, 3, 44),
  ('room-45', 'offensive-security', 4, 'Exploitation Concepts in Controlled Labs', 'Master the mechanics of exploit payloads: shellcode execution, reverse shells vs bind shells, listener configuration, and Metasploit fundamentals.', 50, 3, 45),
  ('room-46', 'offensive-security', 4, 'Reporting and Remediation', 'Transform technical findings into executive business value: writing penetration testing reports, severity risk ratings, and actionable remediation roadmaps.', 50, 3, 46),
  ('room-47', 'offensive-security', 4, 'Offensive Security Capstone', 'Synthesize your complete offensive training: conduct a full-scope simulated authorized penetration test, chain vulnerabilities, and produce an executive remediation report.', 50, 3, 47)
